	}
	if stdout.Len() == 0 {
		t.Error("Run(-h) wrote nothing to stdout, want usage")
	}
}

func TestRunValidUsageIsNotUsageError(t *testing.T) {
	valid := [][]string{
		{"a.csv"},
		{"--column", "name", "a.csv"},
		{"--freq", "--top", "5", "a.csv"},
		{"--freq", "a.csv"},
	}
