		var stdout, stderr bytes.Buffer
		code := Run(args, &stdout, &stderr)
		if code == ExitUsage {
			t.Errorf("Run(%q) = %d, want a non-usage code", args, code)
		}
	}
}

func TestParseCapturesOptions(t *testing.T) {
	tests := []struct {
		name string
		args []string
		want options
	}{
		{name: "file only", args: []string{"a.csv"}, want: options{file: "a.csv"}},
		{name: "column", args: []string{"--column", "name", "a.csv"}, want: options{file: "a.csv", column: "name"}},
		{name: "freq with top", args: []string{"--freq", "--top", "7", "a.csv"}, want: options{file: "a.csv", freq: true, top: 7}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parse(tt.args, &bytes.Buffer{})
			if err != nil {
				t.Fatalf("parse(%q) error = %v", tt.args, err)
			}
			if got != tt.want {
				t.Errorf("parse(%q) = %+v, want %+v", tt.args, got, tt.want)
			}
		})
	}
}

